export const FIGHTERS=[
 {id:0,first:'JIN',last:'KAZAMA',tag:"L'ÉCLAIR DU DESTIN",origin:'JAPON',style:'Karaté Mishima',description:"Le sang des Mishima. La volonté d'un Kazama. Frappez vite, enchaînez fort, et laissez parler la foudre.",power:4,speed:4,range:3,color:'#ff435d',kanji:'仁'},
 {id:1,first:'KAZUYA',last:'MISHIMA',tag:'LE POUVOIR DU DÉMON',origin:'JAPON',style:'Karaté Mishima',description:'Une puissance implacable. Punissez chaque erreur avec des coups électriques et des frappes dévastatrices.',power:5,speed:2,range:4,color:'#b287ff',kanji:'魔'},
 {id:2,first:'JUN',last:'KAZAMA',tag:'LA LUMIÈRE SILENCIEUSE',origin:'JAPON',style:'Arts martiaux Kazama',description:'La grâce rencontre la force. Gardez votre calme, trouvez une ouverture et transformez la défense en victoire.',power:3,speed:4,range:4,color:'#a8e5ed',kanji:'純'},
 {id:3,first:'REINA',last:'',tag:'LA FOUDRE POURPRE',origin:'JAPON',style:'Taido × Karaté Mishima',description:'Insaisissable et électrique. Imposez votre rythme avec une vitesse explosive et des attaques imprévisibles.',power:3,speed:5,range:3,color:'#c096ff',kanji:'麗'}
];
export const MOVES={jab:{startup:.09,active:.11,recovery:.14,range:112,damage:7,knock:15,stun:.23,pose:2},kick:{startup:.16,active:.14,recovery:.23,range:152,damage:12,knock:35,stun:.3,pose:3},upper:{startup:.21,active:.14,recovery:.3,range:110,damage:15,knock:25,stun:.55,launch:190,pose:2},heat:{startup:.24,active:.2,recovery:.43,range:195,damage:27,knock:85,stun:.65,pose:2}};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export class Game{
 constructor({p1=0,p2=1,mode='arcade',difficulty='normal',onEvent=()=>{},random=Math.random}={}){this.ids=[p1,p2];this.mode=mode;this.difficulty=difficulty;this.onEvent=onEvent;this.random=random;this.wins=[0,0];this.round=1;this.phase='intro';this.phaseTime=0;this.time=60;this.elapsed=0;this.paused=false;this.trainingAI=false;this.resetFighters();}
 resetFighters(){this.fighters=this.ids.map((id,i)=>({id,x:i?690:270,y:0,vy:0,hp:100,heat:30,face:i?-1:1,state:'idle',move:null,moveTime:0,hitDone:false,stun:0,block:false,combo:0,comboTime:0,aiWait:0,walk:0,flash:0,heatTime:0}));this.time=60;}
 emit(type,data={}){this.onEvent({type,...data});}
 action(i,kind){const f=this.fighters[i];if(this.paused||this.phase!=='fight'||f.stun>0)return false;if(kind==='jump'){if(f.y===0&&!f.move){f.vy=330;f.state='jump';this.emit('jump',{i});return true;}return false;}if(!MOVES[kind]||f.move||f.block)return false;if(kind==='heat'&&f.heat<100){this.emit('noheat',{i});return false;}if(kind==='heat'){f.heat=0;f.heatTime=.85;this.emit('heat',{i,x:f.x});}f.move=kind;f.moveTime=0;f.hitDone=false;f.state=kind;return true;}
 ai(dt){const f=this.fighters[1],p=this.fighters[0],d=Math.abs(f.x-p.x),difficulty=this.difficulty;f.aiWait-=dt;const c={left:false,right:false,block:false};if(f.stun>0)return c;const target=difficulty==='easy'?128:100;if(d>target+20)c[f.x>p.x?'left':'right']=true;if(d<72)c[f.x>p.x?'right':'left']=true;const defend=difficulty==='hard'?.8:difficulty==='normal'?.45:.17;if(p.move&&d<180&&f.aiWait<0&&this.random()<defend){f.aiWait=.16;c.block=true;return c;}if(f.aiWait>0&&f.state==='block'){c.block=true;return c;}if(f.aiWait<0&&d<165){const r=this.random();let move=f.heat>=100&&r<.3?'heat':r<.48?'jab':r<.83?'kick':'upper';if(d<MOVES[move].range+(FIGHTERS[f.id].range-3)*9-5){this.action(1,move);f.aiWait=difficulty==='easy'?.7+this.random()*.5:difficulty==='hard'?.18+this.random()*.25:.35+this.random()*.35;}}return c;}
 hit(i,move){const a=this.fighters[i],b=this.fighters[1-i],meta=FIGHTERS[a.id];if(Math.abs(a.x-b.x)>move.range+(meta.range-3)*9||Math.abs(a.y-b.y)>100||(b.x-a.x)*a.face<0)return false;const blocked=b.block&&b.y===0;const damage=blocked?Math.ceil(move.damage*.12):Math.round(move.damage*(.9+meta.power*.04)*(a.combo>=3?.85:1));b.hp=Math.max(0,b.hp-damage);b.flash=.13;b.stun=blocked?.1:move.stun;b.x=clamp(b.x+a.face*(blocked?8:move.knock),55,905);if(!blocked){b.move=null;b.state='hit';if(move.launch)b.vy=move.launch;a.combo=a.comboTime>0?a.combo+1:1;a.comboTime=1.1;}a.heat=clamp(a.heat+(blocked?4:13),0,100);b.heat=clamp(b.heat+8,0,100);this.emit(blocked?'block':'hit',{i,damage,combo:a.combo,x:(a.x+b.x)/2+20*a.face,y:385-(a.y+b.y)/2,heavy:a.move==='heat'||a.move==='upper',color:meta.color});return true;}
 update(dt,input=[{},{}]){dt=clamp(dt,0,.05);if(this.paused||this.phase==='done')return;this.elapsed+=dt;this.phaseTime+=dt;if(this.phase==='intro'){if(this.phaseTime>=2){this.phase='fight';this.phaseTime=0;this.emit('fight');}return;}if(this.phase==='roundEnd'){if(this.phaseTime>=2.4){if(this.wins.some(w=>w>=2)){this.phase='done';this.emit('matchEnd',{winner:this.winner,wins:[...this.wins]});}else{this.round++;this.resetFighters();this.phase='intro';this.phaseTime=0;this.emit('round',{round:this.round});}}return;}
 if(this.mode!=='training')this.time=Math.max(0,this.time-dt);const controls=[input[0]||{},this.mode==='versus'?input[1]||{}:(this.mode==='training'&&!this.trainingAI?{}:this.ai(dt))];
 this.fighters.forEach((f,i)=>{const c=controls[i],other=this.fighters[1-i];f.face=other.x>=f.x?1:-1;f.stun=Math.max(0,f.stun-dt);f.flash=Math.max(0,f.flash-dt);f.heatTime=Math.max(0,f.heatTime-dt);f.comboTime=Math.max(0,f.comboTime-dt);if(f.comboTime===0)f.combo=0;f.block=!!c.block&&!f.move&&f.stun===0&&f.y===0;let movement=0;if(!f.move&&f.stun===0&&!f.block){movement=(Number(!!c.right)-Number(!!c.left))*(165+FIGHTERS[f.id].speed*13)*dt;f.x=clamp(f.x+movement,55,905);f.state=movement?'walk':f.y>0?'jump':'idle';}if(f.block)f.state='block';if(f.stun>0)f.state='hit';f.walk+=Math.abs(movement)*.045;if(f.y>0||f.vy>0){f.y=Math.max(0,f.y+f.vy*dt);f.vy-=840*dt;if(f.y===0&&f.vy<0){f.vy=0;this.emit('land',{i,x:f.x});}}if(f.move){f.moveTime+=dt;const move=MOVES[f.move];if(f.moveTime>=move.startup&&f.moveTime<=move.startup+move.active&&!f.hitDone){f.hitDone=this.hit(i,move);}if(f.moveTime>move.startup+move.active+move.recovery){f.move=null;f.state='idle';}}});
 const [a,b]=this.fighters,dist=b.x-a.x;if(Math.abs(dist)<95&&Math.abs(a.y-b.y)<95){const push=(95-Math.abs(dist))/2,sign=dist>=0?1:-1;a.x=clamp(a.x-push*sign,55,905);b.x=clamp(b.x+push*sign,55,905);}
 if(this.mode==='training'){this.fighters.forEach(f=>{if(f.hp<=0){f.hp=100;f.heat=100;f.stun=0;f.move=null;this.emit('resetTraining');}});return;}
 if(a.hp<=0||b.hp<=0||this.time<=0){const winner=a.hp===b.hp?-1:a.hp>b.hp?0:1;this.winner=winner;if(winner>=0)this.wins[winner]++;this.phase='roundEnd';this.phaseTime=0;this.emit('roundEnd',{winner,ko:a.hp<=0||b.hp<=0});}
 }
}
